import { Component, h, Prop, Watch, Element, Host } from '@stencil/core/internal';
import _ds from '../../../typescript/dot-stash';
import CssClassList from '../../types/css-class-list.interface';

@Component({
  tag: 'ds-header',
  styleUrl: 'header.scss'
})
export class DSTitle {
  CSSClassList: CssClassList;
  titleProps: {
    block?: boolean;
    page?: boolean;
    content?: boolean;
    section?: boolean;
  } = {};

  @Prop({ reflect: true }) mods: string | string[] = [];
  @Element() container: HTMLElement;


  @Watch('mods')
  modsChangeHandler( mods: string | string[] ) {
    this.CSSClassList = _ds.props.toClassList("ds-header", _ds.props.toArray(mods));
  }

  componentWillLoad() {
    this.CSSClassList = _ds.props.toClassList("ds-header", _ds.props.toArray(this.mods));
    const parentSlot = this.container.slot;
    if (parentSlot) {
      const [context] = parentSlot.split('-');
      if (context) {
        this.titleProps[context] = true;
      }
    }
  }
  
  render() {
    return (
      <Host
        class={{
          ...this.CSSClassList,
        }}
      >
        <div class="ds-header__before">
          <slot name="before" />
        </div>
        <div class="ds-header__content">
          <hlgroup>
            <ds-title {...this.titleProps}>
              <slot name="title" />
            </ds-title>
            <slot name="sub-title" />
          </hlgroup>
          <slot />
        </div>
        <div class="ds-header__after">
          <slot name="after" />
        </div>
      </Host>
    );
  }
}


